import React from "react";
import DeleteOutlineOutlinedIcon from "@mui/icons-material/DeleteOutlineOutlined";
import PlayArrowOutlinedIcon from "@mui/icons-material/PlayArrowOutlined";
import PauseOutlinedIcon from "@mui/icons-material/PauseOutlined";
import {
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  useMediaQuery,
} from "@mui/material";
import { C } from "../../theme/pbxTokens";
import {
  CALL_COUNT_BREADCRUMB_SEGMENTS,
  CALL_COUNT_COLUMNS,
  CALL_COUNT_COMPACT_MQ,
  CALL_COUNT_DIRECTION_OPTIONS,
  CALL_COUNT_EMPTY_MESSAGE,
  CALL_COUNT_FILTER_MODAL_TITLE,
  CALL_COUNT_FOOTER_LIMIT_NOTE,
  CALL_COUNT_STATUS_OPTIONS,
  CALL_COUNT_TABLE_MIN_WIDTH,
  CALL_COUNT_TALK_DURATION_OPERATOR_OPTIONS,
} from "../../constants/CallCountConstants";
import {
  Btn,
  TH,
  ExtensionTableListLoading as TableListLoading,
  ExtensionTableListEmptyState as TableListEmptyState,
  ExtensionPagination as CallCountPagination,
  MessageBanner,
  extensionPageWrapStyle as pbxPageWrapStyle,
  extensionPageInnerStyle as pbxPageInnerStyle,
  extensionCardStyle as callCountCardStyle,
  extensionToolbarStyle as callCountToolbarStyle,
  extensionSelectedBadgeStyle as callCountSelectedBadgeStyle,
  extensionCancelBtnStyle as callCountCancelBtnStyle,
  RecordingActionBtn,
  RecordingPlayerBar,
} from "../../components/common";
import { useCallCountPage } from "./hooks/useCallCountPage";
import {
  FilterDate,
  FilterField,
  FilterSearch,
  FilterSelect,
  PageBreadcrumb,
  Pill,
} from "./components/CallCountFormFields";
import {
  CALL_COUNT_FILTER_TIME_RANGE_MAX_WIDTH,
  TRUNK_TABLE_SCROLL_CLASS,
  cardBorderSoft,
  callCountFilterBoxFillStyle,
  callCountFilterModalFooterBtnStyle,
  callCountFilterModalCancelBtnStyle,
  callCountFilterModalFooterStyle,
  callCountFilterModalFormStyle,
  callCountFilterModalGridStyle,
  callCountFilterModalPaperSx,
  callCountFilterModalTitleStyle,
  callCountTableTdStyle,
  callCountTableThStyle,
  callCountToolbarFilterRefreshBtnStyle,
  getCallCountCellPadding,
  getCallCountHeaderPadding,
  nativeFieldInteraction,
} from "./components/CallCountTableHelpers";
import {
  formatDate,
  formatDuration,
  getDirection,
  getRowKey,
  hasRecording,
  statusStyle,
} from "./utils/CallCountTransformers";

const columns = CALL_COUNT_COLUMNS;
const CallCount = () => {
  const isCompact = useMediaQuery(CALL_COUNT_COMPACT_MQ);
  const {
    rows,
    loading,
    isInitialLoad,
    error,
    setError,
    message,
    setMessage,
    page,
    selectedIds,
    setSelectedIds,
    lastUpdated,
    showModifyModal,
    setShowModifyModal,
    modifyDraft,
    setModifyDraft,
    filterDraft,
    setFilterDraft,
    appliedFilters,
    appliedModifyDraft,
    recording,
    audioRef,
    filteredData,
    totalPages,
    hasActiveFilters,
    stopRecording,
    loadCdr,
    handlePageChange,
    handleToggleRow,
    handleToggleAll,
    updateFilterDraftDate,
    handleModifyOpen,
    handleFilterSearch,
    handleFilterCancel,
    handleModifyReset,
    handleDelete,
    handleDownload,
    handlePlayRecording,
    handleDeleteRecording,
  } = useCallCountPage();
  return (
    <div style={{ ...pbxPageWrapStyle, padding: isCompact ? 12 : 16 }}>
      <div style={pbxPageInnerStyle}>
        <MessageBanner
          message={message}
          onClose={() => setMessage({ type: "", text: "" })}
        />

        {/* Error banner */}
        {error && (
          <div
            style={{
              background: "#fef2f2",
              borderLeft: `3px solid ${C.amber}`,
              color: "#DC2626",
              padding: "10px 14px",
              borderRadius: 8,
              marginBottom: 16,
              fontSize: 13,
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <span>{error}</span>
            <span
              onClick={() => setError("")}
              style={{ cursor: "pointer", fontSize: 16, color: "#DC2626" }}
            >
              ✕
            </span>
          </div>
        )}

        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            flexWrap: "wrap",
            gap: 12,
            marginBottom: 16,
          }}
        >
          <PageBreadcrumb
            segments={CALL_COUNT_BREADCRUMB_SEGMENTS}
            style={{ marginBottom: 0 }}
          />
          {lastUpdated && (
            <span
              style={{ fontSize: 12, color: C.mutedText, whiteSpace: "nowrap" }}
            >
              Last updated: {lastUpdated.toLocaleTimeString()}
            </span>
          )}
        </div>

        <div style={callCountCardStyle}>
          <div
            style={{
              ...callCountToolbarStyle,
              ...(isCompact
                ? { flexDirection: "column", alignItems: "stretch" }
                : {}),
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              {selectedIds.length > 0 && (
                <span style={callCountSelectedBadgeStyle}>
                  {selectedIds.length} selected
                </span>
              )}
            </div>

            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 10,
                flexWrap: "wrap",
                ...(isCompact
                  ? { width: "100%", justifyContent: "flex-end" }
                  : {}),
              }}
            >
              {!hasActiveFilters ? (
                <Btn
                  onClick={handleModifyOpen}
                  disabled={loading}
                  variant="cancel"
                  style={callCountToolbarFilterRefreshBtnStyle}
                >
                  Filter
                </Btn>
              ) : (
                <Btn
                  onClick={handleModifyReset}
                  disabled={loading}
                  variant="cancel"
                  style={callCountToolbarFilterRefreshBtnStyle}
                >
                  Reset
                </Btn>
              )}
              <Btn
                onClick={() => loadCdr(page)}
                disabled={loading}
                variant="cancel"
                style={callCountToolbarFilterRefreshBtnStyle}
              >
                {loading ? (
                  <CircularProgress size={11} style={{ color: "#374151" }} />
                ) : (
                  "Refresh"
                )}
              </Btn>
              <Btn
                onClick={handleDelete}
                disabled={loading || selectedIds.length === 0}
                variant="cancel"
                style={callCountCancelBtnStyle}
              >
                <DeleteOutlineOutlinedIcon sx={{ fontSize: 16 }} />
                Delete
              </Btn>
              <Btn
                type="button"
                onClick={() => {
                  if (selectedIds.length > 0) {
                    setSelectedIds([]);
                  } else {
                    handleToggleAll();
                  }
                }}
                disabled={filteredData.length === 0}
                variant="cancel"
                style={callCountCancelBtnStyle}
              >
                {selectedIds.length > 0 ? "Deselect All" : "Select All"}
              </Btn>
              <Btn
                onClick={handleDownload}
                disabled={loading}
                variant="cancel"
                style={callCountCancelBtnStyle}
              >
                ⬇ Download CDR
              </Btn>
            </div>
          </div>

          {isInitialLoad ? (
            <TableListLoading />
          ) : rows.length === 0 && !hasActiveFilters ? (
            <TableListEmptyState
              message={CALL_COUNT_EMPTY_MESSAGE}
              showButton={false}
            />
          ) : (
            <>
              <div
                className={TRUNK_TABLE_SCROLL_CLASS}
                style={{
                  overflowX: "auto",
                  overflowY: "auto",
                  flex: 1,
                  WebkitOverflowScrolling: "touch",
                }}
              >
                <table
                  style={{
                    width: "100%",
                    minWidth: CALL_COUNT_TABLE_MIN_WIDTH,
                    borderCollapse: "separate",
                    borderSpacing: 0,
                    tableLayout: "auto",
                  }}
                >
                  <colgroup>
                    {columns.map((col) => (
                      <col key={col.key} style={{ width: col.width }} />
                    ))}
                  </colgroup>
                  <thead>
                    <tr>
                      {columns.map((col, colIdx) => (
                        <TH
                          key={col.key}
                          style={{
                            ...callCountTableThStyle,
                            width: col.width,
                            padding: getCallCountHeaderPadding(col.key),
                            position: "sticky",
                            top: 0,
                            zIndex: 10,
                            ...(colIdx === 0 ? { borderLeft: "none" } : {}),
                            ...(colIdx === columns.length - 1
                              ? { borderRight: "none" }
                              : {}),
                          }}
                        >
                          {col.label}
                        </TH>
                      ))}
                    </tr>
                  </thead>
                  <tbody
                    key={`${appliedFilters.callStatus}-${appliedFilters.direction}-${appliedFilters.search}`}
                  >
                    {filteredData.length === 0 ? (
                      <tr>
                        <td
                          colSpan={columns.length}
                          style={{
                            textAlign: "center",
                            padding: "40px 16px",
                            color: C.mutedText,
                            fontSize: 14,
                            borderBottom: "none",
                          }}
                        >
                          {hasActiveFilters
                            ? "No records match the current filters on this page."
                            : "No records found."}
                        </td>
                      </tr>
                    ) : (
                      filteredData.map((row, idx) => {
                        const isLastRow = idx === filteredData.length - 1;
                        const lastRowCellStyle = isLastRow
                          ? { borderBottom: "none" }
                          : {};
                        const isSelected =
                          row.uniqueid &&
                          selectedIds.includes(String(row.uniqueid));
                        const rowBg = isSelected
                          ? "#eff6ff"
                          : idx % 2 === 1
                            ? "#f8fafc"
                            : "#ffffff";

                        return (
                          <tr
                            key={`${getRowKey(row, idx)}-${isSelected ? "1" : "0"}`}
                            onClick={() => {
                              if (row.uniqueid) {
                                handleToggleRow(String(row.uniqueid));
                              }
                            }}
                            style={{
                              background: rowBg,
                              cursor: row.uniqueid ? "pointer" : "default",
                            }}
                          >
                            <td
                              title={formatDate(row.calldate)}
                              style={{
                                ...callCountTableTdStyle,
                                padding: getCallCountCellPadding("calldate"),
                                background: "inherit",
                                borderLeft: "none",
                                ...lastRowCellStyle,
                              }}
                            >
                              {formatDate(row.calldate)}
                            </td>

                            <td
                              title={row.src || ""}
                              style={{
                                ...callCountTableTdStyle,
                                padding: getCallCountCellPadding("src"),
                                background: "inherit",
                                ...lastRowCellStyle,
                              }}
                            >
                              {row.src || (
                                <span style={{ color: C.mutedText }}>—</span>
                              )}
                            </td>

                            <td
                              title={row.src_ip || ""}
                              style={{
                                ...callCountTableTdStyle,
                                padding: getCallCountCellPadding("src_ip"),
                                background: "inherit",
                                ...lastRowCellStyle,
                              }}
                            >
                              {row.src_ip || (
                                <span style={{ color: C.mutedText }}>—</span>
                              )}
                            </td>

                            <td
                              title={row.dst || ""}
                              style={{
                                ...callCountTableTdStyle,
                                padding: getCallCountCellPadding("dst"),
                                background: "inherit",
                                ...lastRowCellStyle,
                              }}
                            >
                              {row.dst || (
                                <span style={{ color: C.mutedText }}>—</span>
                              )}
                            </td>

                            <td
                              title={row.dst_ip || ""}
                              style={{
                                ...callCountTableTdStyle,
                                padding: getCallCountCellPadding("dst_ip"),
                                background: "inherit",
                                ...lastRowCellStyle,
                              }}
                            >
                              {row.dst_ip || (
                                <span style={{ color: C.mutedText }}>—</span>
                              )}
                            </td>

                            <td
                              style={{
                                ...callCountTableTdStyle,
                                padding:
                                  getCallCountCellPadding("call_direction"),
                                background: "inherit",
                                ...lastRowCellStyle,
                              }}
                            >
                              {getDirection(row) || (
                                <span style={{ color: C.mutedText }}>—</span>
                              )}
                            </td>

                            <td
                              style={{
                                ...callCountTableTdStyle,
                                padding: getCallCountCellPadding("disposition"),
                                background: "inherit",
                                ...lastRowCellStyle,
                              }}
                            >
                              {row.disposition ? (
                                (() => {
                                  const s = statusStyle(row.disposition);
                                  return (
                                    <Pill
                                      text={row.disposition}
                                      bg={s.bg}
                                      color={s.color}
                                    />
                                  );
                                })()
                              ) : (
                                <span style={{ color: C.mutedText }}>—</span>
                              )}
                            </td>

                            <td
                              style={{
                                ...callCountTableTdStyle,
                                padding: getCallCountCellPadding("billsec"),
                                background: "inherit",
                                ...lastRowCellStyle,
                              }}
                            >
                              {formatDuration(row.billsec)}
                            </td>

                            <td
                              title={row.dcontext || ""}
                              style={{
                                ...callCountTableTdStyle,
                                padding: getCallCountCellPadding("dcontext"),
                                background: "inherit",
                                ...lastRowCellStyle,
                              }}
                            >
                              {row.dcontext || (
                                <span style={{ color: C.mutedText }}>—</span>
                              )}
                            </td>

                            <td
                              title={row.hangup_cause || ""}
                              style={{
                                ...callCountTableTdStyle,
                                padding:
                                  getCallCountCellPadding("hangup_cause"),
                                background: "inherit",
                                ...lastRowCellStyle,
                              }}
                            >
                              {row.hangup_cause || (
                                <span style={{ color: C.mutedText }}>—</span>
                              )}
                            </td>

                            <td
                              style={{
                                ...callCountTableTdStyle,
                                padding: getCallCountCellPadding("recording"),
                                background: "inherit",
                                borderRight: "none",
                                whiteSpace: "nowrap",
                                overflow: "visible",
                                ...lastRowCellStyle,
                              }}
                            >
                              {hasRecording(row) ? (
                                <div
                                  onClick={(e) => e.stopPropagation()}
                                  style={{
                                    display: "inline-flex",
                                    gap: 6,
                                    justifyContent: "center",
                                  }}
                                >
                                  <RecordingActionBtn
                                    variant="play"
                                    title={
                                      recording.uniqueid === row.uniqueid &&
                                      recording.url
                                        ? "Stop"
                                        : "Play recording"
                                    }
                                    onClick={() => handlePlayRecording(row)}
                                    disabled={
                                      recording.loading &&
                                      recording.uniqueid === row.uniqueid
                                    }
                                  >
                                    {recording.loading &&
                                    recording.uniqueid === row.uniqueid ? (
                                      <CircularProgress
                                        size={13}
                                        sx={{ color: C.accent }}
                                      />
                                    ) : recording.uniqueid === row.uniqueid &&
                                      recording.url ? (
                                      <PauseOutlinedIcon
                                        sx={{ fontSize: 14 }}
                                      />
                                    ) : (
                                      <PlayArrowOutlinedIcon
                                        sx={{ fontSize: 14 }}
                                      />
                                    )}
                                  </RecordingActionBtn>
                                  <RecordingActionBtn
                                    variant="delete"
                                    title="Delete recording"
                                    onClick={() => handleDeleteRecording(row)}
                                  >
                                    <DeleteOutlineOutlinedIcon
                                      sx={{ fontSize: 14 }}
                                    />
                                  </RecordingActionBtn>
                                </div>
                              ) : (
                                <span style={{ color: C.mutedText }}>—</span>
                              )}
                            </td>
                          </tr>
                        );
                      })
                    )}
                  </tbody>
                </table>
              </div>

              {filteredData.length > 0 && (
                <CallCountPagination
                  page={page}
                  totalPages={totalPages}
                  recordCount={filteredData.length}
                  recordLabel="record"
                  onPageChange={handlePageChange}
                />
              )}
            </>
          )}
        </div>

        <RecordingPlayerBar
          ref={audioRef}
          open={Boolean(recording.url || recording.loading)}
          loading={recording.loading}
          label="Recording"
          src={recording.url}
          onEnded={stopRecording}
          onClose={stopRecording}
          isCompact={isCompact}
          accentColor={C.accent}
        />

        <Dialog
          open={showModifyModal}
          onClose={() => setShowModifyModal(false)}
          maxWidth={false}
          PaperProps={{ sx: callCountFilterModalPaperSx }}
        >
          <DialogTitle style={callCountFilterModalTitleStyle}>
            {CALL_COUNT_FILTER_MODAL_TITLE}
          </DialogTitle>

          <DialogContent
            style={{ padding: "24px", backgroundColor: "#ffffff" }}
          >
            <div style={callCountFilterModalFormStyle}>
              <div style={callCountFilterModalGridStyle(isCompact)}>
                <FilterField label="Call Status" tooltipKey="call_status">
                  <FilterSelect
                    aria-label="Call Status"
                    value={filterDraft.callStatus}
                    onChange={(e) => {
                      const value = e.target.value;
                      setFilterDraft((f) => ({ ...f, callStatus: value }));
                    }}
                    options={CALL_COUNT_STATUS_OPTIONS}
                  />
                </FilterField>

                <FilterField label="Direction" tooltipKey="direction">
                  <FilterSelect
                    aria-label="Direction"
                    value={filterDraft.direction}
                    onChange={(e) => {
                      const value = e.target.value;
                      setFilterDraft((f) => ({ ...f, direction: value }));
                    }}
                    options={CALL_COUNT_DIRECTION_OPTIONS}
                  />
                </FilterField>

                <FilterField label="Call From" tooltipKey="call_from">
                  <FilterSearch
                    placeholder="Call From"
                    value={filterDraft.callFrom}
                    onChange={(e) => {
                      const value = e.target.value;
                      setFilterDraft((f) => ({ ...f, callFrom: value }));
                    }}
                  />
                </FilterField>

                <FilterField label="Call To" tooltipKey="call_to">
                  <FilterSearch
                    placeholder="Call To"
                    value={filterDraft.callTo}
                    onChange={(e) => {
                      const value = e.target.value;
                      setFilterDraft((f) => ({ ...f, callTo: value }));
                    }}
                  />
                </FilterField>

                <FilterField label="Trunk Name" tooltipKey="trunk_name">
                  <FilterSearch
                    placeholder="Trunk Name"
                    value={filterDraft.trunkName}
                    onChange={(e) => {
                      const value = e.target.value;
                      setFilterDraft((f) => ({ ...f, trunkName: value }));
                    }}
                  />
                </FilterField>

                <FilterField label="Talk Duration" tooltipKey="talk_duration">
                  <div
                    style={{
                      display: "grid",
                      gridTemplateColumns: "72px 1fr",
                      gap: 8,
                      width: "100%",
                    }}
                  >
                    <FilterSelect
                      aria-label="Talk Duration Operator"
                      fill
                      value={modifyDraft.talkDurationOperator}
                      onChange={(e) =>
                        setModifyDraft((prev) => ({
                          ...prev,
                          talkDurationOperator: e.target.value,
                        }))
                      }
                      options={CALL_COUNT_TALK_DURATION_OPERATOR_OPTIONS}
                    />
                    <input
                      type="number"
                      min="0"
                      value={modifyDraft.talkDurationSeconds}
                      onChange={(e) =>
                        setModifyDraft((prev) => ({
                          ...prev,
                          talkDurationSeconds: e.target.value,
                        }))
                      }
                      placeholder="Seconds"
                      style={callCountFilterBoxFillStyle}
                      {...nativeFieldInteraction}
                    />
                  </div>
                </FilterField>

                <FilterField
                  label="Time Range"
                  tooltipKey="time_range"
                  style={{ maxWidth: CALL_COUNT_FILTER_TIME_RANGE_MAX_WIDTH }}
                >
                  <div
                    style={{
                      display: "grid",
                      gridTemplateColumns: "1fr 1fr",
                      gap: 8,
                      width: "100%",
                    }}
                  >
                    <FilterDate
                      fill
                      aria-label="Start Date"
                      value={filterDraft.startDate}
                      onChange={(e) =>
                        updateFilterDraftDate("startDate", e.target.value)
                      }
                    />
                    <FilterDate
                      fill
                      aria-label="End Date"
                      value={filterDraft.endDate}
                      onChange={(e) =>
                        updateFilterDraftDate("endDate", e.target.value)
                      }
                    />
                  </div>
                </FilterField>
              </div>

              {hasActiveFilters && (
                <div
                  style={{
                    marginTop: 14,
                    paddingTop: 7,
                    borderTop: `1px solid ${cardBorderSoft}`,
                    fontSize: 12,
                    color: C.mutedText,
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                    flexWrap: "wrap",
                    width: "100%",
                  }}
                >
                  <span
                    style={{
                      background: "#eff6ff",
                      color: C.accent,
                      fontWeight: 600,
                      padding: "4px 10px",
                      textAlign: "center",
                      borderRadius: 999,
                      fontSize: 11,
                    }}
                  >
                    Filters active
                  </span>
                  <span>
                    Showing {filteredData.length} of {rows.length} records on
                    this page
                    {(appliedFilters.startDate || appliedFilters.endDate) && (
                      <>
                        {" "}
                        · {appliedFilters.startDate || "…"} to{" "}
                        {appliedFilters.endDate || "…"}
                      </>
                    )}
                  </span>
                </div>
              )}
            </div>
          </DialogContent>

          <DialogActions
            sx={{ p: 0, m: 0 }}
            style={callCountFilterModalFooterStyle}
          >
            <Btn
              onClick={handleFilterSearch}
              variant="primary"
              style={callCountFilterModalFooterBtnStyle}
            >
              Search
            </Btn>
            <Btn
              onClick={handleFilterCancel}
              variant="cancel"
              style={callCountFilterModalCancelBtnStyle}
            >
              Cancel
            </Btn>
          </DialogActions>
        </Dialog>

        <div
          style={{
            width: "100%",
            display: "flex",
            justifyContent: "center",
            marginTop: isCompact ? 14 : 20,
            padding: isCompact ? "0 4px" : 0,
            fontSize: isCompact ? 12 : 13,
            fontWeight: 700,
            color: "#DC2626",
            textAlign: "center",
          }}
        >
          <span>{CALL_COUNT_FOOTER_LIMIT_NOTE}</span>
        </div>
      </div>
    </div>
  );
};

export default CallCount;

import { useEffect, useMemo, useRef, useState } from "react";
import { bulkDeleteCdr, deleteCdrRecording, downloadCdr, fetchCdr, fetchCdrRecording } from "../../../api/apiService";
import { CALL_COUNT_ITEMS_PER_PAGE, CALL_COUNT_MAX_RECORDS } from "../../../constants/CallCountConstants";
import {
  DEFAULT_APPLIED_MODIFY_DRAFT, DEFAULT_FILTERS, matchesCallFrom, matchesCallStatus,
  matchesCallTo, matchesDateRange, matchesDirectionFilter, matchesSearch, matchesTalkDuration, matchesTrunkName,
} from "../utils/CallCountTransformers";

export function useCallCountPage() {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const hasInitialLoadRef = useRef(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState({ type: "", text: "" });
  const [page, setPage] = useState(1);
  const [totalRecords, setTotalRecords] = useState(0);
  const [limit] = useState(CALL_COUNT_ITEMS_PER_PAGE);
  const [selectedIds, setSelectedIds] = useState([]);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [showModifyModal, setShowModifyModal] = useState(false);
  const [modifyDraft, setModifyDraft] = useState({
    trunkName: "",
    callFrom: "",
    callTo: "",
    ...DEFAULT_APPLIED_MODIFY_DRAFT,
  });

  const [filterDraft, setFilterDraft] = useState({ ...DEFAULT_FILTERS });
  const [appliedFilters, setAppliedFilters] = useState({ ...DEFAULT_FILTERS });
  const [appliedModifyDraft, setAppliedModifyDraft] = useState({
    ...DEFAULT_APPLIED_MODIFY_DRAFT,
  });
  const [recording, setRecording] = useState({
    uniqueid: null,
    url: "",
    loading: false,
  });
  const audioRef = useRef(null);
  const recordingUrlRef = useRef("");

  useEffect(() => {
    recordingUrlRef.current = recording.url;
  }, [recording.url]);

  useEffect(
    () => () => {
      if (recordingUrlRef.current) URL.revokeObjectURL(recordingUrlRef.current);
    },
    [],
  );

  useEffect(() => {
    if (recording.url && audioRef.current) {
      audioRef.current.play().catch(() => {});
    }
  }, [recording.url]);

  const stopRecording = () => {
    if (recordingUrlRef.current) URL.revokeObjectURL(recordingUrlRef.current);
    setRecording({ uniqueid: null, url: "", loading: false });
  };

  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: "", text: "" }), 5000);
  };

  const handlePlayRecording = async (row) => {
    const uniqueid = row?.uniqueid;
    if (!uniqueid) return;
    if (recording.uniqueid === uniqueid && recording.url) {
      stopRecording();
      return;
    }
    if (recordingUrlRef.current) URL.revokeObjectURL(recordingUrlRef.current);
    setError("");
    setRecording({ uniqueid, url: "", loading: true });
    try {
      const blob = await fetchCdrRecording(uniqueid);
      const url = URL.createObjectURL(blob);
      setRecording({ uniqueid, url, loading: false });
    } catch (err) {
      const status = err?.response?.status;
      setError(
        status === 404
          ? "Recording not found for this call."
          : "Failed to load recording. Please try again.",
      );
      setRecording({ uniqueid: null, url: "", loading: false });
    }
  };

  const handleDeleteRecording = async (row) => {
    const uniqueid = row?.uniqueid;
    if (!uniqueid) return;
    if (
      !window.confirm(
        "Delete the recording for this call? This cannot be undone.",
      )
    ) {
      return;
    }
    try {
      setLoading(true);
      const res = await deleteCdrRecording(uniqueid);
      if (res && res.response === false) {
        setError(res.message || "Failed to delete recording.");
        return;
      }
      if (recording.uniqueid === uniqueid) stopRecording();
      setRows((prev) =>
        prev.map((r) =>
          r.uniqueid === uniqueid ? { ...r, recordingfile: "" } : r,
        ),
      );
    } catch {
      setError("Failed to delete recording. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const loadCdr = async (pageToLoad = page, filters = appliedFilters) => {
    try {
      setLoading(true);
      setError("");
      const requestFilters = {
        startdate: filters.startDate || undefined,
        enddate: filters.endDate || undefined,
        trunk_name: filters.trunkName || undefined,
      };

      let activePage = pageToLoad;
      let data = await fetchCdr(activePage, limit, requestFilters);

      if (
        data?.success &&
        Array.isArray(data.data) &&
        data.data.length === 0 &&
        activePage > 1
      ) {
        const apiTotal = Number(data.total);
        const lastValidPage =
          Number.isFinite(apiTotal) && apiTotal >= 0
            ? Math.max(
                1,
                Math.ceil(Math.min(apiTotal, CALL_COUNT_MAX_RECORDS) / limit),
              )
            : activePage - 1;
        if (lastValidPage < activePage) {
          activePage = lastValidPage;
          data = await fetchCdr(activePage, limit, requestFilters);
        }
      }

      if (data && data.success && Array.isArray(data.data)) {
        const pageRows = data.data;
        setRows(pageRows);
        setLastUpdated(new Date());
        const rowCount = pageRows.length;
        const apiTotal = Number(data.total);
        if (Number.isFinite(apiTotal) && apiTotal >= 0) {
          setTotalRecords(Math.min(apiTotal, CALL_COUNT_MAX_RECORDS));
        } else if (rowCount < limit) {
          setTotalRecords(
            Math.min(
              (activePage - 1) * limit + rowCount,
              CALL_COUNT_MAX_RECORDS,
            ),
          );
        }
        setPage(activePage);
      } else {
        setRows([]);
        setTotalRecords(0);
      }
    } catch {
      setError("Failed to load call records. Please try again.");
      setRows([]);
      setTotalRecords(0);
    } finally {
      setLoading(false);
      setIsInitialLoad(false);
    }
  };

  useEffect(() => {
    if (!hasInitialLoadRef.current) {
      hasInitialLoadRef.current = true;
      loadCdr(1);
    }
  }, []);

  const totalPages = useMemo(() => {
    if (totalRecords > 0) {
      return Math.max(1, Math.ceil(totalRecords / limit));
    }
    const hasNextPage = rows.length >= limit;
    return Math.max(1, page + (hasNextPage ? 1 : 0));
  }, [totalRecords, rows.length, limit, page]);

  const handlePageChange = (nextPage) => {
    const next = Math.min(totalPages, Math.max(1, nextPage));
    if (next === page || loading) return;
    if (next > page && rows.length < limit) return;
    loadCdr(next);
  };

  const handleToggleRow = (uniqueid) => {
    const id = String(uniqueid ?? "");
    if (!id) return;
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id],
    );
  };

  const filteredData = useMemo(() => {
    return rows.filter((row) => {
      if (!matchesCallStatus(row, appliedFilters.callStatus)) return false;
      if (!matchesDirectionFilter(row, appliedFilters.direction)) return false;
      if (!matchesSearch(row, appliedFilters.search)) return false;
      if (!matchesTrunkName(row, appliedFilters.trunkName)) return false;
      if (!matchesCallFrom(row, appliedFilters.callFrom)) return false;
      if (!matchesCallTo(row, appliedFilters.callTo)) return false;
      if (
        !matchesTalkDuration(
          row,
          appliedModifyDraft.talkDurationOperator,
          appliedModifyDraft.talkDurationSeconds,
        )
      ) {
        return false;
      }
      if (
        !matchesDateRange(row, appliedFilters.startDate, appliedFilters.endDate)
      ) {
        return false;
      }
      return true;
    });
  }, [
    rows,
    appliedFilters,
    appliedModifyDraft.talkDurationOperator,
    appliedModifyDraft.talkDurationSeconds,
  ]);

  const handleToggleAll = () => {
    const pageIds = filteredData
      .map((r) => String(r.uniqueid ?? ""))
      .filter(Boolean);
    if (!pageIds.length) return;
    const allSelected = pageIds.every((id) => selectedIds.includes(id));
    setSelectedIds((prev) =>
      allSelected
        ? prev.filter((id) => !pageIds.includes(id))
        : Array.from(new Set([...prev, ...pageIds])),
    );
  };

  const hasActiveFilters = useMemo(() => {
    return (
      appliedFilters.callStatus !== "all" ||
      appliedFilters.direction !== "all" ||
      !!appliedFilters.search.trim() ||
      !!appliedFilters.trunkName.trim() ||
      !!appliedFilters.callFrom.trim() ||
      !!appliedFilters.callTo.trim() ||
      !!String(appliedModifyDraft.talkDurationSeconds || "").trim() ||
      !!appliedFilters.startDate ||
      !!appliedFilters.endDate
    );
  }, [appliedFilters, appliedModifyDraft.talkDurationSeconds]);

  const updateFilterDraftDate = (field, value) => {
    const nextStart = field === "startDate" ? value : filterDraft.startDate;
    const nextEnd = field === "endDate" ? value : filterDraft.endDate;
    if (nextStart && nextEnd && nextStart > nextEnd) {
      setError("Start date cannot be after end date.");
      return;
    }
    setError("");
    setFilterDraft((f) => ({ ...f, [field]: value }));
  };

  const handleResetFilters = () => {
    const resetFilters = { ...DEFAULT_FILTERS };
    setFilterDraft(resetFilters);
    setAppliedFilters(resetFilters);
    setAppliedModifyDraft({ ...DEFAULT_APPLIED_MODIFY_DRAFT });
    setModifyDraft({
      trunkName: "",
      callFrom: "",
      callTo: "",
      ...DEFAULT_APPLIED_MODIFY_DRAFT,
    });
    setSelectedIds([]);
    setPage(1);
    setTotalRecords(0);
    setError("");
    loadCdr(1, resetFilters);
  };

  const handleModifyOpen = () => {
    setFilterDraft({ ...appliedFilters });
    setModifyDraft((m) => ({
      ...m,
      talkDurationOperator: appliedModifyDraft.talkDurationOperator,
      talkDurationSeconds: appliedModifyDraft.talkDurationSeconds,
    }));
    setShowModifyModal(true);
  };

  const handleFilterSearch = () => {
    const { startDate, endDate } = filterDraft;
    if (startDate && endDate && startDate > endDate) {
      setError("Start date cannot be after end date.");
      return;
    }
    setError("");
    setAppliedFilters({ ...filterDraft });
    setAppliedModifyDraft({
      talkDurationOperator: modifyDraft.talkDurationOperator,
      talkDurationSeconds: modifyDraft.talkDurationSeconds,
    });
    setPage(1);
    setTotalRecords(0);
    loadCdr(1, filterDraft);
    setShowModifyModal(false);
  };

  const handleFilterCancel = () => {
    setFilterDraft({ ...appliedFilters });
    setModifyDraft((m) => ({
      ...m,
      talkDurationOperator: appliedModifyDraft.talkDurationOperator,
      talkDurationSeconds: appliedModifyDraft.talkDurationSeconds,
    }));
    setShowModifyModal(false);
  };

  const handleModifyReset = () => {
    setShowModifyModal(false);
    handleResetFilters();
  };

  const handleDelete = async () => {
    if (!selectedIds.length) {
      window.alert("Please select at least one record to delete.");
      return;
    }

    const msg =
      selectedIds.length === 1
        ? "Are you sure you want to delete this record?"
        : `Are you sure you want to delete ${selectedIds.length} records?`;

    if (!window.confirm(msg)) return;

    const deleteCount = selectedIds.length;

    try {
      setLoading(true);

      // Bulk delete API call (single request)
      await bulkDeleteCdr(selectedIds);

      setSelectedIds([]);

      const newTotalRecords = Math.max(0, totalRecords - deleteCount);

      const pageToLoad =
        totalRecords > 0
          ? Math.min(
              page,
              Math.max(1, Math.ceil(newTotalRecords / limit))
            )
          : page;

      await loadCdr(pageToLoad);

      showMessage(
        "success",
        `Deleted ${deleteCount} call count record(s)`
      );
    } catch (error) {
      console.error("Bulk delete failed:", error);

      setError(
        "Failed to delete some records. Please refresh and try again."
      );
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = async () => {
    try {
      setLoading(true);
      const response = await downloadCdr();
      const blob = response.data;
      const cd = response.headers?.["content-disposition"] || "";
      let fileName = "cdr.csv";
      const match = /filename\*=UTF-8''([^;]+)|filename="?([^";]+)"?/i.exec(cd);
      if (match)
        fileName = decodeURIComponent(match[1] || match[2] || fileName);
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = fileName;
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      setError("Failed to download CDR file. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return {
    rows,
    loading,
    isInitialLoad,
    error,
    setError,
    message,
    setMessage,
    page,
    totalRecords,
    limit,
    selectedIds,
    setSelectedIds,
    lastUpdated,
    showModifyModal,
    setShowModifyModal,
    modifyDraft,
    setModifyDraft,
    filterDraft,
    setFilterDraft,
    appliedFilters,
    appliedModifyDraft,
    recording,
    audioRef,
    filteredData,
    totalPages,
    hasActiveFilters,
    stopRecording,
    loadCdr,
    handlePageChange,
    handleToggleRow,
    handleToggleAll,
    updateFilterDraftDate,
    handleResetFilters,
    handleModifyOpen,
    handleFilterSearch,
    handleFilterCancel,
    handleModifyReset,
    handleDelete,
    handleDownload,
    handlePlayRecording,
    handleDeleteRecording,
  };
}

