export const E1PriNumManipulateModalFormFields = ({
  fields,
  fieldTooltips,
  formData,
  handleInputChange,
  labelWidth = 170,
}) => (
  <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
    <div style={e1PriNumManipulateFormPanelStyle}>
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        {fields.map((field) => (
          <E1PriNumManipulateFieldRow
            key={field.name}
            label={field.label}
            tooltipKey={field.name}
            tooltips={fieldTooltips}
            labelWidth={labelWidth}
          >
            {field.type === "select" ? (
              <select
                name={field.name}
                value={formData[field.name] || ""}
                onChange={handleInputChange}
                style={e1PriNumManipulateSelectStyle}
                {...e1PriNumManipulateInputInteraction}
              >
                {(field.options || []).length > 0 ? (
                  field.options.map((opt) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))
                ) : field.emptyOptionLabel != null ? (
                  <option value="">{field.emptyOptionLabel}</option>
                ) : null}
              </select>
            ) : (
              <input
                type={field.type || "text"}
                name={field.name}
                value={formData[field.name] || ""}
                onChange={handleInputChange}
                style={e1PriNumManipulateInputStyle}
                {...e1PriNumManipulateInputInteraction}
              />
            )}
          </E1PriNumManipulateFieldRow>
        ))}
      </div>
    </div>
  </div>
);

