  borderRadius: 999,
  border: `1px solid ${C.accent}`,
};

const pcmPstnCancelBtnStyle = {
  height: 30,
  padding: "6px 14px",
  fontSize: 12,
  borderRadius: 4,   
  background: "#cbd5e1",
  color: "#374151",
  border: "1px solid #cbd5e1",
  boxShadow: "0 1px 2px rgba(15, 23, 42, 0.08)",
};

const pcmPstnPrimaryBtnStyle = {
  height: 30,
  padding: "6px 14px",
  fontSize: 12,

  boxShadow: "0 1px 2px rgba(15, 23, 42, 0.08)",
  borderRadius: 4,
};

const PCM_PSTN_MODAL_TAB_BAR_STYLE = {
  borderBottom: "1px solid #e5e7eb",
  background: "#ffffff",
};

const PCM_PSTN_MODAL_TAB_ACTIVE_COLOR = "#3E5475";
const PCM_PSTN_MODAL_TAB_INACTIVE_COLOR = "#374151";

const pcmPstnModalTabsSx = {
  minHeight: 45,
  "& .MuiTab-root": {
    color: PCM_PSTN_MODAL_TAB_INACTIVE_COLOR,
    fontSize: 12,
    fontWeight: 500,
    textTransform: "none",
    minHeight: 45,
  },
  "& .MuiTab-root.Mui-selected": {
    color: PCM_PSTN_MODAL_TAB_ACTIVE_COLOR,
    fontWeight: 700,
  },
};

/** Page layout / modal chrome used by PcmPstnPage.jsx */
export {
  PCM_PSTN_ADD_NEW_DIALOG_SX,
  PCM_PSTN_ADD_NEW_DIALOG_PAPER_SX,
  PCM_PSTN_MODAL_TAB_BAR_STYLE,
  PCM_PSTN_MODAL_TAB_ACTIVE_COLOR,
  pcmPstnModalTabsSx,
  pcmPstnModalFormPanelStyle,
  addNewModalFooterStyle,
  addNewModalFooterBtnStyle,
  pcmPstnModalCancelBtnStyle,
  pcmPstnFooterStyle,
  pcmPstnPrimaryBtnStyle,
  pcmPstnTableCheckboxSx,
};

const PRIMARY_CHANNEL = "1-15,17-31";
const PRIMARY_HDLC = "16";
const SECONDARY_CHANNEL = "32-46,48-62";
const SECONDARY_HDLC = "47";

const normalizeChannelString = (value = "") =>
  String(value || "").replace(/\s+/g, "");

export function usePcmPstnPage() {
const isCompact = useMediaQuery(PCM_PSTN_COMPACT_MQ);
  const [allData, setAllData] = useState([]);
  const [data, setData] = useState([]);
  const [selectedItems, setSelectedItems] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState(PCM_PSTN_INITIAL_FORM);
  const [editIndex, setEditIndex] = useState(-1);
  const [tab, setTab] = useState(0);
  const [loading, setLoading] = useState({
    fetch: false,
    save: false,
    delete: false,
  });
  const [message, setMessage] = useState({ type: "", text: "" });
  const hasInitialLoadRef = useRef(false);
  const pollingRef = useRef(null);
  const silentRefreshRef = useRef(false);
  const lastVisibilityStateRef = useRef(document.visibilityState);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  // Load data on component mount
  useEffect(() => {
    // Prevent duplicate calls during React StrictMode or development double-rendering
    if (!hasInitialLoadRef.current) {
      hasInitialLoadRef.current = true;
      loadPstnData();
    }

    // Start background polling to auto-refresh status
    // Poll faster when the tab is visible, slower when hidden
    const startPolling = () => {
      if (pollingRef.current) return; // already running
      const getIntervalMs = () =>
        document.visibilityState === "visible" ? 5000 : 15000;
      let intervalMs = getIntervalMs();
      pollingRef.current = setInterval(() => {
        loadPstnData(true).catch(() => {});
        // If visibility changed since last tick, adjust interval
        const current = getIntervalMs();
        if (current !== intervalMs) {
          clearInterval(pollingRef.current);
          pollingRef.current = null;
          intervalMs = current;
          startPolling();
        }
      }, intervalMs);
    };

    // Visibility/focus handlers: immediate refresh on return to tab or window focus
    const handleVisibilityChange = () => {
      if (
        document.visibilityState === "visible" &&
        lastVisibilityStateRef.current !== "visible"
      ) {
        loadPstnData(true).catch(() => {});
      }
      lastVisibilityStateRef.current = document.visibilityState;
      // Restart polling to update cadence
      if (pollingRef.current) {
        clearInterval(pollingRef.current);
        pollingRef.current = null;
      }
      startPolling();
    };
    const handleWindowFocus = () => {
      loadPstnData(true).catch(() => {});
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    window.addEventListener("focus", handleWindowFocus);
    startPolling();

    // Cleanup
    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      window.removeEventListener("focus", handleWindowFocus);
      if (pollingRef.current) {
        clearInterval(pollingRef.current);
        pollingRef.current = null;
      }
    };
  }, []);

  // Message handling
  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: "", text: "" }), 5000);
  };

  // Handlers
  const handleInputChange = (name, value) =>
    setFormData((prev) => ({ ...prev, [name]: value }));

  // Load PSTN data from API
  const loadPstnData = async (isRefresh = false) => {
    if (isRefresh) {
      if (silentRefreshRef.current) return;
      silentRefreshRef.current = true;
    } else {
      if (loading.fetch) return;
      setLoading((prev) => ({ ...prev, fetch: true }));
    }

    try {
      console.log("Attempting to load PSTN data...");
      const response = await listPstn();
      console.log("PSTN response:", response);

      if (response && response.success && Array.isArray(response.output)) {
        setAllData(response.output);
        setData(response.output);
        console.log(
          "PSTN data loaded successfully:",
          response.output.length,
          "items",
        );
        console.log("Sample data structure:", response.output[0]); // Debug: show first item structure
      } else {
        console.log("Invalid response format:", response);
        showMessage("error", "Failed to load PSTN data");
      }
    } catch (error) {
      console.error("Error loading PSTN data:", error);
      if (!isRefresh) {
        // Only show error on initial load, not on refresh after operations
        if (error.message === "Network Error") {
          showMessage("error", "Network error. Please check your connection.");
        } else if (error.response?.status === 500) {
          showMessage(
            "error",
            "Server error. The PSTN endpoint may have issues.",
          );
        } else if (error.response?.status === 404) {
          showMessage(
            "error",
            "PSTN API endpoint not found. The server does not have the /pstn endpoint implemented yet.",
          );
        } else {
          showMessage("error", error.message || "Failed to load PSTN data");
        }
      } else {
        // For refresh errors, just log them - don't disturb the user
        console.warn("Refresh failed, keeping existing data:", error.message);
      }
      // Only set empty array on initial load failure, not on refresh
      if (!isRefresh) {
        setAllData([]);
        setData([]);
      }
    } finally {
      if (isRefresh) {
        silentRefreshRef.current = false;
      } else {
        setLoading((prev) => ({ ...prev, fetch: false }));
        setIsInitialLoad(false);
      }
    }
  };

  const getNextAvailableSpanId = () => {
    if (allData.length === 0) {
      return 1;
    }

    // Get all existing span_id values as numbers
    const existingSpanIds = allData
      .map((item) => Number(item.span_id || item.span?.id))
      .sort((a, b) => a - b);

    // Find the first gap in the sequence
    for (let i = 1; i <= Math.max(...existingSpanIds) + 1; i++) {
      if (!existingSpanIds.includes(i)) {
        return i;
      }
    }

    // If no gaps, return the next number after the highest
    return Math.max(...existingSpanIds) + 1;
  };

  const getAvailableSpanNos = () => {
    if (allData.length === 0) {
      return [1, 2, 3, 4, 5]; // Show first 5 available numbers
    }

    // Get all existing SpanNo values as numbers
    const existingSpanNos = allData.map((item) => Number(item.spanNo));
    const maxSpanNo = Math.max(...existingSpanNos);

    // Find available numbers (gaps and next numbers)
    const availableSpanNos = [];
    for (let i = 1; i <= maxSpanNo + 5; i++) {
      if (!existingSpanNos.includes(i)) {
        availableSpanNos.push(i);
        if (availableSpanNos.length >= 5) break; // Show max 5 available numbers
      }
    }

    return availableSpanNos;
  };



  const handleRefresh = async () => {
    await loadPstnData(true);
  };

  const handleInverse = () => {
    const ids = data.map((item) => item.span_id || item.span?.id);
    setSelectedItems(ids.filter((id) => !selectedItems.includes(id)));
  };
  const handleDelete = async () => {
    if (selectedItems.length === 0) {
      showMessage("error", "Please select items to delete");
      return;
    }

    // Show browser confirmation dialog
    const confirmed = window.confirm(
      `Are you sure you want to delete ${selectedItems.length} selected item(s)?`,
    );
    if (!confirmed) {
      return;
    }

    setLoading((prev) => ({ ...prev, delete: true }));
    try {
      console.log("Deleting selected items:", selectedItems);
      const deletePromises = selectedItems.map(async (spanId) => {
        console.log("Deleting item:", spanId);
        return await deletePstn(spanId);
      });

      const results = await Promise.allSettled(deletePromises);
      const successCount = results.filter(
        (result) => result.status === "fulfilled" && result.value.success,
      ).length;
      const failCount = results.length - successCount;

      if (successCount > 0) {
        showMessage("success", `${successCount} item(s) deleted successfully`);

        // Try to reload data, but don't fail if it doesn't work
        try {
          await loadPstnData(true);
        } catch (reloadError) {
          console.warn(
            "Failed to reload after delete, removing from local state:",
            reloadError,
          );
          // Remove deleted items from local state as fallback
          setAllData((prev) =>
            prev.filter(
              (item) => !selectedItems.includes(item.span_id || item.span?.id),
            ),
          );
          setData((prev) =>
            prev.filter(
              (item) => !selectedItems.includes(item.span_id || item.span?.id),
            ),
          );
        }
        setSelectedItems([]); // Clear selection
      }

      if (failCount > 0) {
        showMessage("error", `Failed to delete ${failCount} item(s)`);
      }
    } catch (error) {
      console.error("Error deleting PSTN settings:", error);
      if (error.message === "Network Error") {
        showMessage("error", "Network error. Please check your connection.");
      } else {
        showMessage("error", error.message || "Failed to delete PSTN settings");
      }
    } finally {
      setLoading((prev) => ({ ...prev, delete: false }));
    }
  };
  const handleClearAll = async () => {
    if (allData.length === 0) {
      showMessage("info", "No data to clear");
      return;
    }

    if (
      !window.confirm(
        "Are you sure you want to delete ALL PSTN settings? This action cannot be undone.",
      )
    ) {
      return;
    }

    setLoading((prev) => ({ ...prev, delete: true }));
    try {
      console.log(
        "Clearing all PSTN settings:",
        allData.map((item) => item.span_id || item.span?.id),
      );
      const deletePromises = allData.map(async (item) => {
        const spanId = item.span_id || item.span?.id;
        console.log("Deleting item:", spanId);
        return await deletePstn(spanId);
      });

      const results = await Promise.allSettled(deletePromises);
      const successCount = results.filter(
        (result) => result.status === "fulfilled" && result.value.success,
      ).length;
      const failCount = results.length - successCount;

      if (successCount > 0) {
        showMessage(
          "success",
          `All ${successCount} item(s) deleted successfully`,
        );

        // Try to reload data, but don't fail if it doesn't work
        try {
          await loadPstnData(true);
        } catch (reloadError) {
          console.warn(
            "Failed to reload after clear all, clearing local state:",
            reloadError,
          );
          // Clear all items from local state as fallback
          setAllData([]);
          setData([]);
        }
        setSelectedItems([]);
      }

      if (failCount > 0) {
        showMessage("error", `Failed to delete ${failCount} item(s)`);
      }
    } catch (error) {
      console.error("Error clearing all PSTN settings:", error);
      if (error.message === "Network Error") {
        showMessage("error", "Network error. Please check your connection.");
      } else {
        showMessage(
          "error",
          error.message || "Failed to clear all PSTN settings",
        );
      }
    } finally {
      setLoading((prev) => ({ ...prev, delete: false }));
    }
  };

  const handleAddNew = () => {
    const nextSpanId = getNextAvailableSpanId();
    const normalizedPrimary = normalizeChannelString(PRIMARY_CHANNEL);
    const existingChannels = allData.map((item) =>
      normalizeChannelString(item.span?.bchan || item.bchan),
    );
    const hasPrimary = existingChannels.includes(normalizedPrimary);

    const newFormData = {
      ...PCM_PSTN_INITIAL_FORM,
      id: nextSpanId,
      bchan: hasPrimary ? SECONDARY_CHANNEL : PRIMARY_CHANNEL,
      hardhdlc: hasPrimary ? SECONDARY_HDLC : PRIMARY_HDLC,
    };
    setFormData(newFormData);
    setEditIndex(-1);
    setTab(0);
    setIsModalOpen(true);
  };

  const handleEditItem = (item, index) => {
    // Map the new API response structure to form data
    const formData = {
      // Span fields
      id: item.span?.id || item.span_id || "",
      timing: String(item.span?.timing || 0),
      lbo: String(item.span?.lbo || 0),
      framing: item.span?.framing || "",
      coding: item.span?.coding || "",
      flags:
        item.span?.flags === false ||
        item.span?.flags === undefined ||
        item.span?.flags === null
          ? "Disabled"
          : item.span?.flags === true
            ? "crc4"
            : String(item.span?.flags || "crc4"),
      bchan: item.span?.bchan || "",
      hardhdlc: item.span?.hardhdlc || "",

      // Channels fields
      signalling: item.channels?.signalling || "",
      context: item.channels?.context || "",
      switchtype: item.channels?.switchtype || "",
      group: item.channels?.group || 1,
      accountcode: item.channels?.accountcode || "",
      pickupgroup: item.channels?.pickupgroup || 1,
      callgroup: item.channels?.callgroup || 1,
      pridialplan: item.channels?.pridialplan || "",
      prilocaldialplan: item.channels?.prilocaldialplan || "",
      facilityenable: item.channels?.facilityenable || "yes",
      usecallerid: item.channels?.usecallerid || "yes",
      hidecallerid: item.channels?.hidecallerid || "no",
      usecallingpres: item.channels?.usecallingpres || "yes",
      immediate: item.channels?.immediate || "no",
      overlapdial: item.channels?.overlapdial || "yes",
      faxdetect: item.channels?.faxdetect || "no",

      // Voice fields
      rxgain: String(item.channels?.rxgain || 0.0),
      txgain: String(item.channels?.txgain || 0.0),
      echocancel: item.channels?.echocancel || "yes",
      echocancelwhenbridged: item.channels?.echocancelwhenbridged || "yes",
    };

    setFormData(formData);
    setEditIndex(index);
    setTab(0);
    setIsModalOpen(true);
  };

  const handleSave = async () => {
    // Validate form data
    const validationErrors = validateFormData(formData, editIndex, allData);
    if (validationErrors.length > 0) {
      const errorMessage = validationErrors.join(", ");
      showMessage("error", errorMessage);
      return;
    }

    setLoading((prev) => ({ ...prev, save: true }));
    try {
      // Prepare data for new API structure
      // Build span object with the exact tokens expected by DAHDI (no booleans)
      const spanPayload = {
        id: parseInt(formData.id),
        timing: parseInt(formData.timing) || 0,
        lbo: parseInt(formData.lbo) || 0,
        framing: formData.framing,
        coding: formData.coding,
        bchan: formData.bchan,
        hardhdlc: formData.hardhdlc,
        zones: {
          loadzone: "in",
          defaultzone: "in",
        },
      };
      // Only include flags when enabled; send string token like 'crc4', not boolean
      if (formData.flags && formData.flags !== "Disabled") {
        spanPayload.flags = formData.flags; // e.g., 'crc4', 'yellow', 'nt', 'te', 'term'
      }

      const apiData = {
        span_id: parseInt(formData.id),
        span: spanPayload,
        channels: {
          channel: formData.bchan, // Use same value as bchan
          signalling: formData.signalling,
          context: formData.context,
          switchtype: formData.switchtype,
          group: parseInt(formData.group) || 1,
          language: "en", // Hardcoded
          accountcode: formData.accountcode,
          pickupgroup: parseInt(formData.pickupgroup) || 1,
          callgroup: parseInt(formData.callgroup) || 1,
          pridialplan: formData.pridialplan,
          prilocaldialplan: formData.prilocaldialplan,
          facilityenable: formData.facilityenable,
          usecallerid: formData.usecallerid,
          hidecallerid: formData.hidecallerid,
          usecallingpres: formData.usecallingpres,
          echocancel: formData.echocancel,
          echocancelwhenbridged: formData.echocancelwhenbridged,
          immediate: formData.immediate,
          overlapdial: formData.overlapdial,
          faxdetect: formData.faxdetect,
          rxgain: parseFloat(formData.rxgain) || 0.0,
          txgain: parseFloat(formData.txgain) || 0.0,
        },
      };

      console.log("Creating PSTN with data:", apiData);
      const response = await createPstn(apiData);
      console.log("Create response:", response);

      if (response && response.success) {
        // Close modal to prevent further edits while processing
        setIsModalOpen(false);
        setEditIndex(-1);
        setLoading((prev) => ({ ...prev, fetch: true }));

        // Reload data immediately and then show success message
        try {
          await loadPstnData(true);
          showMessage(
            "success",
            response.message || "PSTN settings saved successfully!",
          );
        } catch (reloadError) {
          console.warn(
            "Failed to reload PSTN data after creation:",
            reloadError,
          );
          showMessage(
            "success",
            response.message || "PSTN settings saved successfully!",
          );
        }
      } else {
        const apiMessage = response?.message || response?.error;
        showMessage(
          "error",
          apiMessage ||
            "Failed to save PSTN settings. Please verify your inputs and try again.",
        );
      }
    } catch (error) {
      console.error("Error saving PSTN settings:", error);
      let friendlyMessage =
        "Failed to save PSTN settings. Please verify your inputs and try again.";
      if (error.response?.status === 400) {
        friendlyMessage =
          error.response?.data?.message ||
          "Invalid PSTN data. Please check the fields and try again.";
      } else if (error.response?.status === 409) {
        friendlyMessage =
          error.response?.data?.message ||
          "A PSTN span with this ID already exists.";
      } else if (error.response?.status === 500) {
        friendlyMessage =
          "Server error while saving PSTN settings. The span configuration may be invalid or already in use.";
      } else if (error.message === "Network Error") {
        friendlyMessage =
          "Network error. Please check your connection and try again.";
      } else if (error.message) {
        friendlyMessage = error.message;
      }
      showMessage("error", friendlyMessage);
    } finally {
      setLoading((prev) => ({ ...prev, save: false }));
    }
  };

  // Render helpers

  const renderTableRow = (row, idx, isLastRow = false) => {
    const realIndex = idx;
    const spanId = row.span_id || row.span?.id;
    const isRowChecked = selectedItems.includes(spanId);
    const rowBg = isRowChecked
      ? "#eff6ff"
      : idx % 2 === 1
        ? "#f8fafc"
        : "#ffffff";
    const lastRowCellStyle = isLastRow ? { borderBottom: "none" } : {};

    return (
      <tr
        key={spanId}
        style={{
          background: rowBg,
          transition: "background 0.15s ease",
        }}
        onMouseEnter={(e) => {
          if (!isRowChecked) e.currentTarget.style.background = "#f8fafc";
        }}
        onMouseLeave={(e) => {
          if (!isRowChecked) e.currentTarget.style.background = rowBg;
        }}
      >
        <td
          style={{
            ...tdStyle,
            background: rowBg,
            width: 36,
            borderLeft: "none",
            ...lastRowCellStyle,
          }}
        >
          <Checkbox
            size="small"
            checked={isRowChecked}
            onChange={() => {
              setSelectedItems((prev) =>
                selectedItems.includes(spanId)
                  ? prev.filter((i) => i !== spanId)
                  : [...prev, spanId],
              );
            }}
            disabled={loading.delete}
            sx={pcmPstnTableCheckboxSx}
          />
        </td>
        {PCM_PSTN_TABLE_COLUMNS.map((col) => {
          if (col.key === "modify") {
            return (
              <td
                key={col.key}
                style={{
                  ...tdStyle,
                  background: rowBg,
                  borderRight: "none",
                  ...lastRowCellStyle,
                }}
              >
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center",
                  }}
                >
                  <EditDocumentIcon
                    titleAccess="Edit"
                    onClick={() => handleEditItem(row, realIndex)}
                    style={{
                      cursor: loading.delete ? "not-allowed" : "pointer",
                      color: "#2563eb",
                      fontSize: 22,
                      opacity: loading.delete ? 0.4 : 0.7,
                      transition: "opacity 0.15s ease",
                    }}
                    onMouseEnter={(e) => {
                      if (!loading.delete) e.currentTarget.style.opacity = "1";
                    }}
                    onMouseLeave={(e) => {
                      if (!loading.delete) e.currentTarget.style.opacity = "0.7";
                    }}
                  />
                </div>
              </td>
            );
          }
          if (col.key === "span_status") {
            const isUp = row.span_status?.includes("Up");
            return (
              <td
                key={col.key}
                style={{ ...tdStyle, background: rowBg, ...lastRowCellStyle }}
              >
                <span
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: isUp ? C.successGreen : C.errorRed,
                  }}
                >
                  {row.span_status || "—"}
                </span>
              </td>
            );
          }
          // Get value from appropriate section (span, channels, or root)
          const getValue = (key) => {
            if (row.span && row.span[key] !== undefined) return row.span[key];
            if (row.channels && row.channels[key] !== undefined)
              return row.channels[key];
            return row[key];
          };

          // Special handling for specific fields
          const displayValue = (key, value) => {
            if (value === undefined || value === null || value === "")
              return "—";

            // Handle timing field specifically
            if (key === "timing") {
              return value === 0 ? "0" : value === 1 ? "1" : String(value);
            }

            // Handle lbo field specifically
            if (key === "lbo") {
              return value === 0 ? "0" : value === 1 ? "1" : String(value);
            }

            // Handle flags field specifically
            if (key === "flags") {
              if (value === false || value === undefined || value === null) {
                return "Disabled";
              }
              if (value === true) {
                return "crc4";
              }
              return String(value);
            }

            return String(value);
          };

          return (
            <td
              key={col.key}
              style={{ ...tdStyle, background: rowBg, ...lastRowCellStyle }}
            >
              {displayValue(col.key, getValue(col.key))}
            </td>
          );
        })}
      </tr>
    );
  };

  const renderFormField = (field) => {
    const isRequired = ["id", "context", "signalling", "bchan"].includes(
      field.name,
    );
    const labelText = `${field.label}:`;

    return (
      <PcmPstnFieldRow
        key={field.name}
        label={labelText}
        tooltipKey={field.name}
        tooltips={PCM_PSTN_FIELD_TOOLTIPS}
        required={isRequired}
      >
        {field.type === "select" ? (
          <select
            name={field.name}
            value={formData[field.name] ?? ""}
            onChange={(e) => handleInputChange(field.name, e.target.value)}
            style={pcmPstnSelectStyle}
            {...pcmPstnInputInteraction}
          >
            {field.options.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        ) : field.type === "radio" ? (
          <RadioGroup
            row
            value={formData[field.name] || ""}
            onChange={(e) => handleInputChange(field.name, e.target.value)}
          >
            {field.options.map((opt) => (
              <FormControlLabel
                key={opt}
                value={opt}
                control={<Radio size="small" />}
                label={opt}
                sx={{
                  "& .MuiFormControlLabel-label": {
                    fontSize: 13,
                    color: "#374151",
                  },
                }}
              />
            ))}
          </RadioGroup>
        ) : (
          <input
            type={field.type || "text"}
            name={field.name}
            value={formData[field.name] ?? ""}
            onChange={(e) => handleInputChange(field.name, e.target.value)}
            onKeyDown={(e) => {
              if (field.type === "number" && e.key === "e") e.preventDefault();
            }}
            style={pcmPstnInputStyle}
            {...pcmPstnInputInteraction}
          />
        )}
      </PcmPstnFieldRow>
    );
  };

  return {
    allData,
    data,
    selectedItems,
    setSelectedItems,
    isModalOpen,
    setIsModalOpen,
    formData,
    editIndex,
    tab,
    setTab,
    loading,
    message,
    setMessage,
    isInitialLoad,
    isCompact,
    showMessage,
    handleInputChange,
    loadPstnData,
    getNextAvailableSpanId,
    getAvailableSpanNos,
    handleRefresh,
    handleInverse,
    handleDelete,
    handleClearAll,
    handleAddNew,
    handleEditItem,
    handleSave,
    renderTableRow,
    renderFormField,
  };
}

import { useState, useEffect, useRef } from "react";
import useMediaQuery from "@mui/material/useMediaQuery";
import {
  PCM_TRUNK_GROUP_FIELDS,
  PCM_TRUNK_GROUP_INITIAL_FORM,
  PCM_TRUNK_GROUP_TABLE_COLUMNS,
  PCM_TRUNK_GROUP_FIELD_TOOLTIPS,
  PCM_TRUNK_GROUP_PAGE_BREADCRUMB_ROOT,
  PCM_TRUNK_GROUP_PAGE_BREADCRUMB_SECTION,
  PCM_TRUNK_GROUP_PAGE_TITLE,
  PCM_TRUNK_GROUP_EMPTY_MESSAGE,
  PCM_TRUNK_GROUP_MODAL_TITLE_ADD,
  PCM_TRUNK_GROUP_MODAL_TITLE_EDIT,
  PCM_TRUNK_GROUP_ADD_NEW_LABEL,
  PCM_TRUNK_GROUP_DELETE_LABEL,
  PCM_TRUNK_GROUP_SAVE_LABEL,
  PCM_TRUNK_GROUP_CLOSE_LABEL,
} from "../../../../constants/PcmTrunkGroupConstants";
import {
  listPstn,
  listPstnGroups,
  savePstnGroup,
  deletePstnGroup,
  listIpPstnRoutes,
  listNumberManipulations,
} from "../../../../api/apiService";
import { PCM_TRUNK_GROUP_COMPACT_MQ } from "../components/PcmTrunkGroupFormFields";

export function usePcmTrunkGroupPage() {
const isCompact = useMediaQuery(PCM_TRUNK_GROUP_COMPACT_MQ);
  const tableScrollRef = useRef(null);
  const [groups, setGroups] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState(PCM_TRUNK_GROUP_INITIAL_FORM);
  const [checkAll, setCheckAll] = useState(false);
  const [selected, setSelected] = useState([]);
  const [page, setPage] = useState(1);
  const [spansData, setSpansData] = useState([]);
  const [isLoadingSpans, setIsLoadingSpans] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [error, setError] = useState(null);
  const [message, setMessage] = useState({ type: "", text: "" });
  const itemsPerPage = 20;
  const totalPages = Math.max(1, Math.ceil(groups.length / itemsPerPage));
  const pagedGroups = groups.slice(
    (page - 1) * itemsPerPage,
    page * itemsPerPage,
  );

  // Message handling
  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: "", text: "" }), 5000);
  };

  // useEffect(() => {
  //   localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(groups));
  // }, [groups]);

  // Fetch PCM trunk group data on component mount

  useEffect(() => {
    fetchPcmTrunkGroupData();
  }, []);

  const fetchSpansData = async () => {
    setIsLoadingSpans(true);
    try {
      const res = await listPstn();

      // Support various shapes: res.message, res.data, top-level array, or nested
      let raw = [];
      if (Array.isArray(res)) raw = res;
      else if (Array.isArray(res?.message)) raw = res.message;
      else if (Array.isArray(res?.data)) raw = res.data;
      else if (Array.isArray(res?.data?.message)) raw = res.data.message;
      if (!raw.length && res && typeof res === "object") {
        const v = Object.values(res).find(
          (x) =>
            Array.isArray(x) &&
            x.length &&
            (x[0]?.span_id != null || x[0]?.span != null),
        );
        if (v) raw = v;
      }

      const mapped = raw
        .map((it) => {
          const spanId = it?.span_id ?? it?.span ?? it?.spanNo ?? it?.id;
          return spanId != null ? { spanNo: String(spanId) } : null;
        })
        .filter(Boolean);

      setSpansData(mapped);
      if (!mapped.length)
        console.warn("PSTN list returned no spans. Raw:", res);
    } catch (error) {
      console.error("Error fetching spans data:", error);
    } finally {
      setIsLoadingSpans(false);
    }
  };

  const fetchPcmTrunkGroupData = async () => {
    setIsLoadingData(true);
    setError(null); // Clear any previous errors
    try {
      const response = await listPstnGroups();
      if (response?.response && Array.isArray(response.message)) {
        const mapped = response.message.map((g) => ({
          groupId: g.group_id,
          pstnIds: g.pstn_ids || [],
          description: g.description || "",
        }));
        setGroups(mapped);
      } else {
        setGroups([]);
      }
    } catch (error) {
      console.error("Error fetching PSTN groups:", error);
      showMessage("error", error?.message || "Failed to load PSTN groups");
      // On error, keep empty array
      setGroups([]);
    } finally {
      setIsLoadingData(false);
    }
  };

  const handleOpenModal = async (item = null, index = -1) => {
    // Always fetch fresh spans data when opening modal
    await fetchSpansData();

    if (item) {
      // Editing existing item
      setFormData({
        ...item,
        groupId:
          String(item.groupId) !== undefined
            ? Number(item.groupId)
            : item.groupId,
        originalIndex: index,
      });
    } else {
      setFormData({ ...PCM_TRUNK_GROUP_INITIAL_FORM });
    }
    setIsModalOpen(true);
  };

  // Helper function to get used PSTN spans from existing groups
  const getUsedPstnSpans = () => {
    const usedSpans = new Set();
    groups.forEach((group) => {
      if (group.pstnIds && Array.isArray(group.pstnIds)) {
        group.pstnIds.forEach((span) => usedSpans.add(String(span)));
      }
    });
    return usedSpans;
  };

  // Helper function to check if a span is available for selection
  const isSpanAvailable = (
    spanNo,
    isEditing = false,
    editingGroupIndex = null,
  ) => {
    const usedSpans = getUsedPstnSpans();
    const spanStr = String(spanNo);

    // If we're editing an existing group, the spans used by that group should still be available
    if (isEditing && editingGroupIndex !== null) {
      const editingGroup = groups[editingGroupIndex];
      if (
        editingGroup &&
        editingGroup.pstnIds &&
        editingGroup.pstnIds.includes(spanStr)
      ) {
        return true; // This span is used by the group we're editing, so it's available
      }
    }

    return !usedSpans.has(spanStr);
  };
  const handleCloseModal = () => setIsModalOpen(false);

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;

    // Special validation for index field
    if (name === "index") {
      const newIndex = parseInt(value);

      // Check if this index is already used by another item (excluding current item being edited)
      const existingIndexes = groups.map((group) => parseInt(group.index));
      const currentIndex =
        formData.originalIndex !== undefined
          ? parseInt(groups[formData.originalIndex]?.index)
          : null;

      // Remove current item's index from the check if we're editing
      const otherIndexes = existingIndexes.filter(
        (idx) => idx !== currentIndex,
      );

      if (otherIndexes.includes(newIndex)) {
        showMessage(
          "error",
          `Index ${newIndex} is already in use. Please select a different index.`,
        );
        return; // Don't update the form data
      }
    }

    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  // PSTN IDs (checkboxes), use span.spanNo as pstn id string
  const handleTrunkCheckbox = (spanNo) => {
    const isEditing = formData.originalIndex !== undefined;
    const isAvailable = isSpanAvailable(
      spanNo,
      isEditing,
      formData.originalIndex,
    );

    // Don't allow selection of unavailable spans
    if (!isAvailable) {
      return;
    }

    setFormData((prev) => {
      const idStr = String(spanNo);
      const next = prev.pstnIds?.includes(idStr)
        ? prev.pstnIds.filter((t) => t !== idStr)
        : [...(prev.pstnIds || []), idStr];
      return { ...prev, pstnIds: next };
    });
  };
  const handleCheckAll = () => {
    setCheckAll(true);
    // Check all available spans only
    const isEditing = formData.originalIndex !== undefined;
    const available = spansData
      .filter((span) =>
        isSpanAvailable(span.spanNo, isEditing, formData.originalIndex),
      )
      .map((span) => String(span.spanNo));
    setFormData((prev) => ({ ...prev, pstnIds: available }));
  };
  const handleUncheckAll = () => {
    setCheckAll(false);
    setFormData((prev) => ({ ...prev, pstnIds: [] }));
  };

  const handleSave = async () => {
    // Validate form data with better checks
    // Check if groupId is null, undefined, or empty string (but allow 0 as valid)
    if (
      formData.groupId === null ||
      formData.groupId === undefined ||
      formData.groupId === ""
    ) {
      showMessage("error", "Please select a Group ID.");
      return;
    }

    if (!formData.description || formData.description.trim() === "") {
      showMessage("error", "Please fill in the Description field.");
      return;
    }

    if (!formData.pstnIds || formData.pstnIds.length === 0) {
      showMessage("error", "Please select at least one PSTN ID.");
      return;
    }

    // Additional validation for duplicate index
    const newIndex = parseInt(formData.groupId);
    const existingIndexes = groups.map((group) => parseInt(group.groupId));
    const currentIndex =
      formData.originalIndex !== undefined
        ? parseInt(groups[formData.originalIndex]?.groupId)
        : null;
    const otherIndexes = existingIndexes.filter((idx) => idx !== currentIndex);

    if (otherIndexes.includes(newIndex)) {
      showMessage(
        "error",
        `Index ${newIndex} is already in use. Please select a different index.`,
      );
      return;
    }

    setIsSaving(true);

    try {
      // Auto-upgrade index if it's a new entry (not editing existing)
      let finalIndex = parseInt(formData.groupId);
      if (formData.originalIndex === undefined) {
        const existingIndexes = groups.map((group) => parseInt(group.groupId));
        let nextIndex = 0;
        while (existingIndexes.includes(nextIndex)) {
          nextIndex++;
        }
        finalIndex = nextIndex;
      }

      // Check if we're trying to create multiple trunk groups at once
      // If so, we need to create separate entries for each trunk
      if (formData.pstnIds.length > 1 && formData.originalIndex === undefined) {
        // Create multiple trunk groups - one for each selected trunk
        const savePromises = formData.pstnIds.map(
          async (pstnId, trunkIndex) => {
            const trunkGroupIndex = finalIndex + trunkIndex;
            return await savePstnGroup(
              trunkGroupIndex,
              [pstnId],
              `${formData.description}`,
            );
          },
        );

        const results = await Promise.all(savePromises);
        const allSuccessful = results.every(
          (result) => result && result.response,
        );
        if (allSuccessful) {
          const newGroups = formData.pstnIds.map((pstnId, trunkIndex) => ({
            groupId: String(finalIndex + trunkIndex),
            description: formData.description,
            pstnIds: [pstnId],
          }));

          setGroups((prev) => [...prev, ...newGroups]);

          showMessage(
            "success",
            `Successfully created ${formData.pstnIds.length} PSTN group(s)!`,
          );
          setIsModalOpen(false);
          await fetchPcmTrunkGroupData();
        } else {
          showMessage(
            "error",
            "Failed to create some PSTN groups. Please try again.",
          );
        }
      } else {
        const response = await savePstnGroup(
          finalIndex,
          formData.pstnIds,
          formData.description,
        );
        if (response?.response) {
          showMessage("success", "PSTN Group saved successfully!");
          setIsModalOpen(false);
          await fetchPcmTrunkGroupData();
        } else {
          showMessage("error", "Failed to save PSTN Group. Please try again.");
        }
      }
    } catch (error) {
      console.error("Error saving PSTN group:", error);
      if (error.message === "Network Error") {
        showMessage("error", "Network error. Please check your connection.");
      } else {
        showMessage("error", error.message || "Failed to save PSTN group");
      }
    } finally {
      setIsSaving(false);
    }
  };

  const handleSelectRow = (idx) => {
    setSelected((sel) =>
      sel.includes(idx) ? sel.filter((i) => i !== idx) : [...sel, idx],
    );
  };

  const pagedRowIndexes = pagedGroups.map(
    (_, idx) => (page - 1) * itemsPerPage + idx,
  );
  const allPageSelected =
    pagedRowIndexes.length > 0 &&
    pagedRowIndexes.every((idx) => selected.includes(idx));
  const somePageSelected =
    pagedRowIndexes.length > 0 &&
    pagedRowIndexes.some((idx) => selected.includes(idx)) &&
    !allPageSelected;

  const handleToggleAll = () => {
    if (allPageSelected) {
      setSelected((prev) =>
        prev.filter((idx) => !pagedRowIndexes.includes(idx)),
      );
    } else {
      setSelected((prev) => {
        const next = [...prev];
        pagedRowIndexes.forEach((idx) => {
          if (!next.includes(idx)) next.push(idx);
        });
        return next;
      });
    }
  };

  const handleInverse = () => {
    const otherPageSelections = selected.filter(
      (idx) => !pagedRowIndexes.includes(idx),
    );
    const invertedPagedSelections = pagedRowIndexes.filter(
      (idx) => !selected.includes(idx),
    );
    setSelected([...otherPageSelections, ...invertedPagedSelections]);
  };

  const handleCheckAllRows = () => {
    setSelected(pagedRowIndexes);
  };
  const handleUncheckAllRows = () => {
    setSelected([]);
  };

  // Check if PCM trunk group is referenced by routing rules or number manipulations
  const isPcmGroupReferenced = async (groupId) => {
    try {
      const gid = String(groupId);

      // Check routes (PSTN to IP routes use call_source field for PCM trunk groups)
      try {
        const routeRes = await listIpPstnRoutes("pstn_to_ip");
        const routeList =
          (routeRes && (routeRes.message || routeRes.data)) || [];
        const foundInRoutes = routeList.some((item) => {
          try {
            // In RoutePstnToIPpage, callInitiator is mapped to call_source in the API
            const candidates = [
              item?.call_source,
              item?.callSource,
              item?.call_source_id,
              item?.callInitiator,
              item?.call_initiator,
              item?.callInitiatorId,
              item?.call_initiator_id,
              item?.pcm_trunk_group,
              item?.pcm_trunk_group_id,
            ]
              .filter((v) => v !== undefined && v !== null)
              .map((v) => String(v));
            return candidates.some((v) => v === gid);
          } catch {
            return false;
          }
        });
        if (foundInRoutes) return true;
      } catch (e) {
        console.warn("Route reference check failed:", e?.message);
      }

      // Check number manipulations (if they use PCM trunk groups)
      try {
        const manipRes = await listNumberManipulations();
        const manipList =
          (manipRes && (manipRes.message || manipRes.data)) || [];
        const foundInManip = manipList.some((item) => {
          try {
            const candidates = [
              item?.call_source,
              item?.callSource,
              item?.callInitiator,
              item?.call_initiator,
              item?.callInitiatorId,
              item?.call_initiator_id,
              item?.pcm_trunk_group,
              item?.pcm_trunk_group_id,
            ]
              .filter((v) => v !== undefined && v !== null)
              .map((v) => String(v));
            return candidates.some((v) => v === gid);
          } catch {
            return false;
          }
        });
        if (foundInManip) return true;
      } catch (e) {
        console.warn("Number manipulation reference check failed:", e?.message);
      }

      return false;
    } catch (e) {
      console.warn("Reference check failed:", e?.message);
      return false;
    }
  };

  // Delete individual PCM trunk group
  const handleDeleteSelected = async () => {
    if (selected.length === 0) {
      showMessage("error", "Please select at least one item to delete.");
      return;
    }

    const confirmed = window.confirm(
      `Are you sure you want to delete ${selected.length} selected item(s)?`,
    );
    if (!confirmed) return;

    setIsLoadingData(true);
    try {
      let deletedCount = 0;
      let skippedCount = 0;

      for (const idx of selected) {
        const item = groups[idx];
        if (!item || item.groupId == null) continue;

        // Check if group is referenced before deleting
        const inUse = await isPcmGroupReferenced(item.groupId);
        if (inUse) {
          showMessage(
            "error",
            "The PCM trunk group cannot be deleted because it is quoted by the routing rule!",
          );
          skippedCount++;
          continue;
        }

        // Delete the group
        try {
          const response = await deletePstnGroup(String(item.groupId));
          if (response?.response) {
            deletedCount++;
          } else {
            console.warn(
              `Failed to delete group ${item.groupId}:`,
              response?.message,
            );
          }
        } catch (deleteError) {
          console.error(`Error deleting group ${item.groupId}:`, deleteError);
        }
      }

      // Refresh data from server
      await fetchPcmTrunkGroupData();
      setSelected([]);

      if (deletedCount > 0) {
        showMessage(
          "success",
          `Successfully deleted ${deletedCount} item(s)${skippedCount > 0 ? `, ${skippedCount} skipped (in use)` : ""}`,
        );
      } else if (skippedCount > 0) {
        showMessage(
          "warning",
          `No items deleted. ${skippedCount} item(s) are in use and cannot be deleted.`,
        );
      } else {
        showMessage("info", "No items were deleted.");
      }
    } catch (error) {
      console.error("Error deleting selected items:", error);
      if (error.message === "Network Error") {
        showMessage("error", "Network error. Please check your connection.");
      } else {
        showMessage(
          "error",
          error.message || "Failed to delete selected items",
        );
      }
    } finally {
      setIsLoadingData(false);
    }
  };

  // Delete all PCM trunk groups
  const handleClearAll = async () => {
    if (groups.length === 0) {
      showMessage("info", "No PCM trunk groups to clear");
      return;
    }

    const confirmed = window.confirm(
      "Are you sure you want to delete ALL PCM trunk groups? This action cannot be undone.",
    );
    if (!confirmed) return;

    setIsLoadingData(true);
    try {
      let deletedCount = 0;
      let skippedCount = 0;

      for (const group of groups) {
        // Check if group is referenced before deleting
        const inUse = await isPcmGroupReferenced(group.groupId);
        if (inUse) {
          showMessage(
            "error",
            "The PCM trunk group cannot be deleted because it is quoted by the routing rule!",
          );
          skippedCount++;
          continue;
        }

        // Delete the group
        try {
          const response = await deletePstnGroup(String(group.groupId));
          if (response?.response) {
            deletedCount++;
          } else {
            console.warn(
              `Failed to delete group ${group.groupId}:`,
              response?.message,
            );
          }
        } catch (deleteError) {
          console.error(`Error deleting group ${group.groupId}:`, deleteError);
        }
      }

      // Refresh data from server
      await fetchPcmTrunkGroupData();
      setSelected([]);
      setPage(1);

      if (deletedCount > 0) {
        showMessage(
          "success",
          `Successfully deleted ${deletedCount} PCM trunk group(s)${skippedCount > 0 ? `, ${skippedCount} skipped (in use)` : ""}`,
        );
      } else if (skippedCount > 0) {
        showMessage(
          "warning",
          `No groups deleted. ${skippedCount} group(s) are in use and cannot be deleted.`,
        );
      } else {
        showMessage("info", "No groups were deleted.");
      }
    } catch (error) {
      console.error("Error deleting all PCM trunk groups:", error);
      if (error.message === "Network Error") {
        showMessage("error", "Network error. Please check your connection.");
      } else {
        showMessage(
          "error",
          error.message || "Failed to delete all PCM trunk groups",
        );
      }
    } finally {
      setIsLoadingData(false);
    }
  };

  return {
    groups,
    isModalOpen,
    formData,
    checkAll,
    selected,
    page,
    setPage,
    spansData,
    isLoadingSpans,
    isSaving,
    isLoadingData,
    message,
    setMessage,
    isCompact,
    tableScrollRef,
    itemsPerPage,
    totalPages,
    pagedGroups,
    showMessage,
    fetchSpansData,
    fetchPcmTrunkGroupData,
    handleOpenModal,
    getUsedPstnSpans,
    isSpanAvailable,
    handleCloseModal,
    handleInputChange,
    handleTrunkCheckbox,
    handleCheckAll,
    handleUncheckAll,
    handleSave,
    handleSelectRow,
    pagedRowIndexes,
    allPageSelected,
    somePageSelected,
    handleToggleAll,
    handleInverse,
    handleCheckAllRows,
    handleUncheckAllRows,
    isPcmGroupReferenced,
    handleDeleteSelected,
    handleClearAll,
  };
}

