                    .map((field) => renderFormField(field))}
                </div>
                {renderAllowCodecsSection()}
              </SipToSipSectionCard>
            </div>
          </div>
        </DialogContent>
        <DialogActions sx={{ p: 0, m: 0 }} style={addNewModalFooterStyle}>
