            </Btn>
            <Btn
              variant="cancel"
              onClick={handleDelete}
              disabled={selected.length === 0}
              style={dialingRuleToolbarCancelBtnStyle}
            >
              Delete
            </Btn>
            <Btn
              variant="cancel"
              onClick={handleClearAll}
              disabled={rules.length === 0}
              style={dialingRuleToolbarCancelBtnStyle}
