import { useEffect, useRef, useState } from "react";
import {
  IP_CALL_IN_CALLEEID_FIELDS,
  IP_CALL_IN_CALLEEID_INITIAL_FORM,
} from "../../../../constants/FxsIPCallInCalleeIDConstants";
import {
  listNumberManipulations,
  createNumberManipulation,
  updateNumberManipulation,
  deleteNumberManipulation,
} from "../../../../api/apiService";
import {
  IPCallInCalleeIDFormFromRow,
  buildIPCallInCalleeIDUpdatePayload,
  normalizeIPCallInCalleeIDFormDigits,
} from "../utils/IPCallInCalleeIDTransformers";
import { validateIPCallInCalleeIDForm } from "../utils/IPCallInCalleeIDValidators";

const IPCALLINCALLEEID_ITEMS_PER_PAGE = 20;

export function useIPCallInCalleeIDPage() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState(IP_CALL_IN_CALLEEID_INITIAL_FORM);
  const [rules, setRules] = useState([]);
  const [selected, setSelected] = useState([]);
  const [page, setPage] = useState(1);
  const itemsPerPage = IPCALLINCALLEEID_ITEMS_PER_PAGE;
  const totalPages = Math.max(1, Math.ceil(rules.length / itemsPerPage));
  const pagedRules = rules.slice(
    (page - 1) * itemsPerPage,
    page * itemsPerPage,
  );
  const [loading, setLoading] = useState({
    fetch: false,
    save: false,
    delete: false,
  });
  const [editIndex, setEditIndex] = useState(null);
  const [toast, setToast] = useState({ msg: "", type: "success" });
  const tableScrollRef = useRef(null);

  const getUpdatedFields = () => IP_CALL_IN_CALLEEID_FIELDS;

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast({ msg: "", type: "success" }), 3500);
  };

  const alert = (msg) => {
    const isErr =
      /error|failed|required|please/i.test(msg) && !/successfully/i.test(msg);
    showToast(msg, isErr ? "error" : "success");
  };

  const fetchNumberManipulations = async () => {
    setLoading((prev) => ({ ...prev, fetch: true }));
    try {
      const response = await listNumberManipulations("ip_in_calleeid");
      if (response.response && response.message) {
        setRules(response.message);
      } else {
        setRules([]);
      }
    } catch (error) {
      console.error("Error fetching number manipulations:", error);
      if (error.message === "Network Error") {
        alert("Network error. Please check your connection.");
      } else if (error.response?.status === 500) {
        alert(
          "Server error. The number manipulations endpoint may have issues.",
        );
      } else {
        alert(error.message || "Failed to load number manipulations");
      }
      setRules([]);
    } finally {
      setLoading((prev) => ({ ...prev, fetch: false }));
    }
  };

  const handleOpenModal = (item = null) => {
    if (item) {
      setFormData(IPCallInCalleeIDFormFromRow(item));
      setEditIndex(item.id);
    } else {
      setFormData({ ...IP_CALL_IN_CALLEEID_INITIAL_FORM });
      setEditIndex(null);
    }
    setIsModalOpen(true);
  };

  const handleCloseModal = () => setIsModalOpen(false);

  const handleSave = async () => {
    const validationError = validateIPCallInCalleeIDForm(formData);
    if (validationError) {
      alert(validationError);
      return;
    }

    const normalized = normalizeIPCallInCalleeIDFormDigits(formData);

    setLoading((prev) => ({ ...prev, save: true }));
    try {
      let response;
      if (editIndex !== null) {
        response = await updateNumberManipulation(
          buildIPCallInCalleeIDUpdatePayload(normalized, editIndex),
          "ip_in_calleeid",
        );
        if (response.response) {
          alert(
            response.message || "Number manipulation updated successfully!",
          );
          try {
            await new Promise((resolve) => setTimeout(resolve, 500));
            await fetchNumberManipulations();
          } catch {
            setRules((prev) =>
              prev.map((rule) =>
                rule.id === editIndex ? { ...rule, ...normalized } : rule,
              ),
            );
          }
        } else {
          alert("Failed to update number manipulation");
        }
      } else {
        response = await createNumberManipulation(
          normalized,
          "ip_in_calleeid",
        );
        if (response.response) {
          alert(
            response.message || "Number manipulation created successfully!",
          );
          try {
            await new Promise((resolve) => setTimeout(resolve, 500));
            await fetchNumberManipulations();
          } catch {
            const newItem = {
              ...normalized,
              id: Date.now(),
              manipulation_type: "ip_in_calleeid",
            };
            setRules((prev) => [...prev, newItem]);
          }
        } else {
          alert("Failed to create number manipulation");
        }
      }
      handleCloseModal();
    } catch (error) {
      console.error("Error saving number manipulation:", error);
