              ...controlSlotStyle,
              width: field.key === "fxoHangupTime" ? "auto" : 220,
              minWidth: 220,
            }}
          >
            <input
              type="text"
              value={form[field.key]}
              onChange={(e) => onChange(field.key, e.target.value)}
              style={fieldInputStyle}
              {...sipCompatibilityNativeFieldInteraction}
            />
            {field.key === "fxoHangupTime" && (
